const listRecoverableHubSignupCompletions = `-- name: ListRecoverableHubSignupCompletions :many
SELECT
    operation_id,
    hub_signup_request_id,
    token_hash,
    idempotency_key,
    request_digest,
    account_email_digest,
    hub_user_did,
    handle,
    reserve_command_id,
    activate_command_id,
    payload_ciphertext,
    state,
    failure_reason,
    conflicting_home_tenant_id,
    provisioning_expires_at,
    attempt_count,
    next_attempt_at,
    last_error,
    created_at,
    updated_at,
    completed_at,
    expires_at
FROM vetchium.hub_signup_completions
WHERE state NOT IN ('completed', 'failed')
  AND next_attempt_at <= now()
ORDER BY next_attempt_at, created_at
LIMIT 25
`

func (q *Queries) ListRecoverableHubSignupCompletions(ctx context.Context) ([]VetchiumHubSignupCompletion, error) {
	rows, err := q.db.Query(ctx, listRecoverableHubSignupCompletions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VetchiumHubSignupCompletion
	for rows.Next() {
		var i VetchiumHubSignupCompletion
		if err := rows.Scan(
			&i.OperationID,
			&i.HubSignupRequestID,
			&i.TokenHash,
			&i.IdempotencyKey,
			&i.RequestDigest,
			&i.AccountEmailDigest,
			&i.HubUserDid,
			&i.Handle,
			&i.ReserveCommandID,
			&i.ActivateCommandID,
			&i.PayloadCiphertext,
			&i.State,
			&i.FailureReason,
			&i.ConflictingHomeTenantID,
			&i.ProvisioningExpiresAt,
			&i.AttemptCount,
			&i.NextAttemptAt,
			&i.LastError,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CompletedAt,
			&i.ExpiresAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

